import {battleAtmosphere} from './battle-presentation.js';
import {presentCombatTurn,combatFieldData,combatEffects,combatSpriteOptions} from './combat-animation.js';
/* Story presentation only. The local demo engine owns combat and reward rules. */
export function createStoryView(env) {
 const {core:C,escape:esc,icon:I,button:btn,sprite,coin,format:n}=env;
 const current=()=>env.getCombat();
 const active=b=>current()===b;
 const later=(b,fn,ms)=>setTimeout(()=>{if(active(b))fn();},ms);
 const sceneClass=chapter=>`mission-scene scene-${chapter.scene||'aurora'}`;
 const stages=phase=>`<div class="mission-stages"><span class="done">${I('info')} Missão</span><i></i><span class="${phase==='travel'?'active':'done'}">${I('story')} Exploração</span><i></i><span class="${phase==='battle'?'active':phase==='reward'?'done':''}">${I('arena')} Batalhas</span><i></i><span class="${phase==='reward'?'active':''}">${I('gift')} Prêmios</span></div>`;
 const waveDots=t=>`<div class="mission-waves">${t.enemies.map((e,i)=>`<span class="${i<t.defeated?'done':i===t.enemyIndex?'active':''}">${i<t.defeated?I('check'):i+1}</span>${i<t.enemies.length-1?'<i></i>':''}`).join('')}<small>${t.defeated}/${t.enemies.length} robôs derrotados</small></div>`;
 function top(b,phase){const c=b.ticket.chapter;return `<div class="mission-top"><span class="eyebrow">CAPÍTULO ${String(c.id).padStart(2,'0')} / ${esc(c.place)}</span><button class="text-btn" data-a="story-exit">${I('close')} Sair</button></div>${stages(phase)}`;}
 async function start(id,uid,mode){
  if(env.getCombat())return;
  try{const resume=!!env.getState().activeStory;let next,ticket;if(env.isDemo){next=C.clone(env.getState());ticket=C.beginStory(next,id,uid);if(!resume&&['auto','manual'].includes(mode))ticket.controlMode=mode;env.setState(next);env.save();}else{await env.remoteAction('story_start',{chapter_id:id,robot_id:uid,control_mode:mode});next=env.getState();ticket=next.activeStory;}
   const b={kind:'story',ticket,phase:ticket.status==='travel'?'travel':'battle',auto:ticket.controlMode!=='manual',autoGeneration:0,busy:false,
    playerHP:ticket.playerHP,enemyHP:ticket.enemyHP,playerRow:0,enemyRow:0,action:'',log:'Seguindo a transmissão…'};
   env.setCombat(b);if(env.syncAudioScene)env.syncAudioScene();else env.audio?.setScene({kind:b.phase==='travel'?'story':'combat',season:C.seasons(env.getState()).find(s=>s.from<=ticket.chapter.id&&s.to>=ticket.chapter.id)});env.audio?.play('start');
   if(ticket.status==='travel'){renderTravel(b);if(next.settings.autoStoryStart)later(b,enter,ticket.rules.travelMs);}
   else if(ticket.status==='fighting'){b.phase='battle';renderBattle(b);schedule(b,ticket.rules.autoDelayMs);}
   else if(ticket.status==='wave-cleared')renderWaveCleared(b);else finish();
  }catch(e){env.toast(e.message,true);}
 }
 function renderTravel(b){const t=b.ticket,c=t.chapter;env.modal(`${top(b,'travel')}<h2 id="modal-title">${esc(c.title)}</h2><div class="mission-travel ${sceneClass(c)}" style="${env.sceneStyle?.(c.scene,c.sceneArt||C.seasonForChapter(env.getState(),c.id)?.sceneArt)||''}">${battleAtmosphere(c.scene)}<div class="scene-grid"></div><div class="mission-location"><span>SINAL DETECTADO</span><b>${esc(c.place)}</b></div><div class="travel-trail"></div><div class="travel-pilot">${sprite(t.player,'travel-sprite')}<span>${esc(t.player.name)}</span></div><div class="travel-destination">${I('core')}<span>Explorar</span></div><div class="mission-particles">${Array.from({length:9},(_,i)=>`<i style="--i:${i}"></i>`).join('')}</div><div class="travel-progress"><i></i></div></div><div class="mission-dialogue"><span>${esc(env.getState().settings.guideName||'NEXA')} · TRANSMISSÃO</span><p>${esc(c.story)}</p><b>${esc(c.objective||'Vença os robôs no caminho e libere o sinal.')}</b></div><div class="mission-preview"><div><small>ROBÔS NO CAMINHO</small><div class="enemy-preview">${t.enemies.map(e=>`<div>${sprite(e.def)}<span>${esc(e.name)}</span></div>`).join('')}</div></div><div class="mission-prize-preview">${coin('RC')}<strong>${t.replay?'Resgate já realizado':n(t.reward)+' RC'}</strong><small>${t.replay?'Entrada de '+t.entryFee.amount+' '+t.entryFee.currency+' · sem novo prêmio':'Ao vencer todos os encontros'}</small></div></div>${btn('Iniciar os encontros '+I('arrow'),'story-skipintro','','secondary wide')}`,'mission-modal');}
 async function enter(){const b=current();if(b?.kind!=='story'||b.phase!=='travel')return;try{if(env.isDemo){C.enterStory(b.ticket);env.save();}else{await env.remoteAction('story_enter');b.ticket=env.getState().activeStory;}}catch(e){env.toast(e.message,true);return;}env.audio?.play('start');b.phase='battle';if(env.syncAudioScene)env.syncAudioScene();else env.audio?.setScene({kind:'combat',season:C.seasons(env.getState()).find(s=>s.from<=b.ticket.chapter.id&&s.to>=b.ticket.chapter.id)});b.log=b.auto?'Um robô bloqueou a passagem. Combate automático iniciado.':'Um robô bloqueou a passagem. Escolha seu movimento.';renderBattle(b);schedule(b,b.ticket.rules.autoDelayMs);}
 function health(name,hp,max,previous=hp){return `<div class="hp"><span>${esc(name)}<b>${Math.max(0,hp)} / ${max}</b></span><div><i style="--old-health:${Math.max(0,previous)/max*100}%;--new-health:${Math.max(0,hp)/max*100}%;width:${Math.max(0,hp)/max*100}%"></i></div></div>`;}
 function renderBattle(b){const t=b.ticket,p=t.player,e=t.enemies[t.enemyIndex],moving=b.busy||b.auto;
  const damage=b.action==='player-attack'||b.action==='special'||b.action==='shield'?b.enemyDamage:b.action==='enemy-attack'?b.playerDamage:0;
  const target=b.action==='enemy-attack'?'player':'enemy';
  env.modal(`${top(b,'battle')}<div class="mission-title"><div><h2 id="modal-title">${esc(t.chapter.title)}</h2><p>${e.boss?'Guardião do capítulo':'Robô hostil encontrado'} · Batalha ${t.enemyIndex+1} de ${t.enemies.length}</p></div><span>TURNO ${Math.max(1,t.round-(b.busy?1:0))}</span></div>${waveDots(t)}<div class="mission-battle ${sceneClass(t.chapter)} action-${b.action||'idle'}" ${combatFieldData(b,env.sceneStyle?.(t.chapter.scene,t.chapter.sceneArt||C.seasonForChapter(env.getState(),t.chapter.id)?.sceneArt)||'')}>${battleAtmosphere(t.chapter.scene)}<div class="scene-grid"></div><div class="combatant mission-player ${b.action==='enemy-attack'&&b.motion==='impact'?'taking-hit':''}">${health(p.name,b.playerHP,p.health,b.previousPlayerHP??b.playerHP)}${sprite(p,'combat-sprite',b.playerRow,combatSpriteOptions(b,'player'))}${b.moveKind==='shield'&&b.busy?'<div class="shield-field"></div>':''}</div><span class="versus">VS</span><div class="combatant mission-enemy ${b.motion==='down'?'actor-defeated':b.action!=='enemy-attack'&&b.motion==='impact'?'taking-hit':''}">${health(e.name,b.enemyHP,e.health,b.previousEnemyHP??b.enemyHP)}${sprite(e.def,'combat-sprite',b.enemyRow,combatSpriteOptions(b,'enemy'))}<span class="enemy-label">${e.boss?'GUARDIÃO':'ROBÔ HOSTIL'}</span></div>${combatEffects(b,I)}<div class="combat-log" role="status">${esc(b.log)}</div></div><div class="mission-control-row"><div class="combat-energy"><span>${I('bolt')} ENERGIA</span>${Array.from({length:t.rules.energyMax},(_,i)=>i).map(i=>`<i class="${i<t.energy?'filled':''}"></i>`).join('')}</div><button class="auto-toggle ${b.auto?'on':''}" data-a="story-toggle-auto">${I(b.auto?'eye':'arena')}${b.auto?'Auto ativado · Assumir controle':'Modo manual · Ativar auto'}</button></div><div class="combat-controls">${btn(I('arena')+' Ataque','combat-move','data-id="attack" '+(moving?'disabled':''),'secondary')}${btn(I('shield')+' Defender','combat-move','data-id="shield" '+(moving?'disabled':''),'secondary')}${btn(I('bolt')+' Especial','combat-move','data-id="special" '+(moving||t.energy<t.rules.energyMax?'disabled':''),'primary')}</div><p class="combat-note">${t.replay?'Rejogando capítulo · prêmio já recebido':`Prêmio de ${n(t.reward)} RC ao concluir o capítulo`} · Produção e moeda de teste</p>`,'mission-modal');
 }
 function schedule(b,ms=b.ticket.rules.autoDelayMs){const generation=b.autoGeneration;later(b,()=>{if(!b.auto||b.busy||b.autoGeneration!==generation||b.ticket.status!=='fighting')return;const t=b.ticket;move(t.energy>=t.rules.energyMax?'special':t.playerHP<t.player.health*.3?'shield':'attack');},ms);}
 async function move(kind){const b=current();if(b?.kind!=='story'||b.busy||b.phase!=='battle'||b.ticket.status!=='fighting')return;
  let result;try{if(env.isDemo)result=C.storyTurn(b.ticket,kind,Math.random());else{b.busy=true;result=await env.remoteAction('story_move',{move:kind});b.ticket=env.getState().activeStory;}}catch(e){b.busy=false;env.toast(e.message,true);schedule(b);return;}
  env.save();presentCombatTurn({battle:b,kind,result,render:renderBattle,later,audio:env.audio,
   onDefeated:()=>{if(result.status==='won')finish();else renderWaveCleared(b);},
   onComplete:()=>{if(result.status==='lost'){finish();return;}b.log=b.auto?'Seu robô se prepara para o próximo movimento.':'Escolha seu próximo movimento.';renderBattle(b);schedule(b);}
  });
 }

 function renderWaveCleared(b){const t=b.ticket;b.phase='between';env.audio?.play('wave');env.modal(`${top(b,'battle')}<div class="wave-cleared"><span class="eyebrow">PASSAGEM LIBERADA</span>${sprite(t.player,'wave-winner',3)}<h2 id="modal-title">Robô derrotado!</h2><p>${esc(t.enemies[t.enemyIndex].name)} foi vencido.<br>Seu robô recupera energia para continuar.</p>${waveDots(t)}<div class="wave-healing">${I('shield')} Recuperação de até ${t.rules.waveHealPercent}% da vida</div><div class="mission-dialogue compact"><span>${esc(env.getState().settings.guideName||'NEXA')} · SINAL LIBERADO</span><p>${esc(t.chapter.interludes?.[t.enemyIndex]||'A passagem está segura. Prepare-se: '+t.enemies[t.enemyIndex+1].name+' protege o próximo sinal.')}</p></div><div class="next-wave-loading"><i></i><span>Avançando para o próximo encontro…</span></div></div>`,'mission-modal');later(b,async()=>{let recovery;try{if(env.isDemo)recovery=C.nextStoryWave(t);else{recovery=await env.remoteAction('story_next');Object.assign(t,env.getState().activeStory);}}catch(e){env.toast(e.message,true);return;}env.save();env.audio?.play('heal',t.player);b.phase='battle';b.busy=false;b.playerHP=t.playerHP;b.enemyHP=t.enemyHP;b.action='';b.motion='idle';b.moveKind='';b.enemyDamage=b.playerDamage=0;b.playerOffset=b.enemyOffset=0;b.playerRow=0;b.enemyRow=0;b.log=`+${recovery.healed} de vida · ${recovery.enemy.name} está no caminho.`;renderBattle(b);schedule(b,t.rules.autoDelayMs);},t.rules.betweenWavesMs);}
 function toggleAuto(){const b=current();if(b?.kind!=='story'||b.phase!=='battle')return;b.auto=!b.auto;b.ticket.controlMode=b.auto?'auto':'manual';env.save();b.autoGeneration++;renderBattle(b);if(b.auto&&!b.busy)schedule(b,b.ticket.rules.autoDelayMs);}
 async function exit(){const b=current();if(b?.kind!=='story')return;if(!env.isDemo){try{await env.remoteAction('story_cancel');}catch(e){env.toast(e.message,true);return;}}else{C.cancelStory(b.ticket);env.getState().activeStory=null;}env.save();env.setCombat(null);env.closeModal();env.render();env.toast(b.ticket.entryFee.amount?'Expedição encerrada. A entrada do replay já foi utilizada.':'Exploração interrompida. Você pode tentar novamente.');}
 async function finish(){const b=current();if(b?.kind!=='story')return;const t=b.ticket,win=t.status==='won';
  try{let state,amount;if(env.isDemo){state=C.clone(env.getState());amount=C.resolveStory(state,t);env.setState(state);env.save();}else{amount=(await env.remoteAction('story_finish')).amount;state=env.getState();}env.setCombat(null);env.render();
   const nextChapter=C.chapters(state).find(c=>c.id===t.chapter.id+1),next=nextChapter?btn('Próximo capítulo '+I('arrow'),'chapter',`data-id="${nextChapter.id}"`):'';env.audio?.play(win?'victory':'lose');
   env.modal(`${stages('reward')}<div class="mission-reward ${win?'won':'lost'}">${win?`<div class="reward-sparkles">${Array.from({length:16},(_,i)=>`<i style="--i:${i}">${coin('RC')}</i>`).join('')}</div><div class="reward-chest">${env.assetUrl?`<img src="${env.assetUrl('reward-chest.png')}" alt="Baú de recompensas">`:I('gift')}</div>`:sprite(t.player,'result-sprite',2)}<span class="eyebrow">${win?'MISSÃO CONCLUÍDA':'EXPEDIÇÃO ENCERRADA'}</span><h2 id="modal-title">${win?'Um novo caminho se abriu.':'Seu próximo passo é evoluir.'}</h2><p>${win?esc(t.chapter.conclusion||'Você venceu os robôs de '+t.chapter.place+'.'):'A equipe precisa de mais força para atravessar este capítulo.'}</p><div class="mission-result-stats"><div><b>${t.defeated}/${t.enemies.length}</b><small>Robôs derrotados</small></div><div><b>${t.turns}</b><small>Movimentos</small></div><div><b>${String(t.chapter.id).padStart(2,'0')}</b><small>Capítulo</small></div></div><div class="mission-prize ${amount?'collected':''}">${coin('RC')}<strong>${amount?'+'+n(amount)+' RC':win?'Prêmio já resgatado':'Nenhum prêmio creditado'}</strong><small>${amount?'RobotCoins adicionadas à sua carteira':win?'Rejogar não repete o resgate':'Tente novamente para conquistar a recompensa'}</small></div>${win?`<div class="mission-unlocked">${I('check')} ${!nextChapter?'Todos os sinais desta campanha foram restaurados':C.seasons(state).some(s=>s.from===nextChapter.id)?'Nova temporada desbloqueada!':esc(nextChapter.title)+' disponível no mapa'}</div>`:''}<div class="mission-result-buttons">${win?next:btn('Tentar novamente','chapter',`data-id="${t.chapter.id}"`)}${btn('Voltar ao mapa','goto','data-page="story"','secondary')}</div></div>`,'mission-modal');
  }catch(e){env.setCombat(null);env.closeModal();env.render();env.toast(e.message,true);}
 }
 return {start,enter,move,toggleAuto,exit};
}
